window.VO = [{"id":"n01","text":"You're the judge.","at":0.24,"t0":0.12,"t1":1.02},{"id":"n02","text":"In a city of two crore people, someone robbed a woman at a chai stall.","at":2.54,"t0":1.27,"t1":5.06},{"id":"n03","text":"Nobody saw his face, but he cut his hand on a glass, and the blood matches this man.","at":10.62,"t0":5.31,"t1":10.085},{"id":"p01","text":"Your Honour, only one person in ten thousand has this blood.","at":21.87,"t0":10.935,"t1":14.775},{"id":"p02","text":"That's a one in ten thousand chance it was someone else.","at":30.05,"t0":15.025,"t1":18.055},{"id":"n04","text":"The blood is all there is. Guilty, or not guilty?","at":36.91,"t0":18.455,"t1":21.51},{"id":"d01","text":"Judge sahab, I wasn't there.","at":43.72,"t0":21.86,"t1":23.46},{"id":"n05","text":"One in ten thousand. And he matches.","at":47.52,"t0":23.76,"t1":26.12},{"id":"n06","text":"You had two numbers. Did you put them together?","at":54.24,"t0":27.12,"t1":29.575},{"id":"n07","text":"Two crore people. One in ten thousand of them.","at":60.65,"t0":30.325,"t1":33.195},{"id":"n08","text":"That's two thousand people with his blood.","at":66.99,"t0":33.495,"t1":35.59},{"id":"n09","text":"So the blood narrows it down to two thousand. It can't tell you which one.","at":72.38,"t0":36.19,"t1":40.15},{"id":"n10","text":"It's called the prosecutor's fallacy, and it fools real judges too.","at":81.1,"t0":40.55,"t1":44.345},{"id":"n11","text":"One of those two thousand, you've met before.","at":89.59,"t0":44.795,"t1":47.155},{"id":"n12","text":"Four films. Same thief. Still free.","at":94.81,"t0":47.405,"t1":49.67},{"id":"n13","text":"Now try it on the friend who's good at maths. Don't tell them it's maths.","at":100.34,"t0":50.17,"t1":53.865},{"id":"n14","text":"So. Where was the thief sitting?","at":108.53,"t0":54.265,"t1":55.91}];
